        private static void Register(string ns, string name, int typeDef, int methods, Func<VisualElement, object> factory)
        {
            var desc = new ScreenDescriptor
            {
                Namespace = ns,
                ClassName = name,
                TypeDefIndex = typeDef,
                MethodCount = methods,
                Factory = factory
            };
            _screens[name] = desc;
            _screens[$"{ns}.{name}"] = desc;
        }

        public static bool TryGetDescriptor(string name, out ScreenDescriptor desc) => _screens.TryGetValue(name, out desc);
        public static object CreateScreen(string name, VisualElement root)
        {
            if (!_initialized) Initialize();
            return _screens.TryGetValue(name, out var d) ? d.Factory(root) : new GenericScreenController(name, 0);
        }
